class NodeBS(object):
    def __init__(self, vl = None):
        self.vl = vl
        self.root = None
        self.lf = None
        self.rg = None
    def _ad(self, vl):
        nd = NodeBS(vl)
        if vl > self.vl:
            self.rg = self.rg and self.rg._ad(vl) or nd
        elif vl < self.vl:
            self.lf = self.lf and self.lf._ad(vl) or nd
        else:
            print("node duplicated")
        return self
class Bst(NodeBS):
    def add_node(self, vl):
        if not self.root:
            self.root = NodeBS(vl)
        else:
            self.root._ad(vl)
    def order(self):
        current = self.root
        nodes, stack = [], []
        while stack or current:
            if current:
                nodes.append(current.vl)
                stack.append(current)
                current = current.lf
            else:
                current = stack.pop()
                current = current.rg
        return nodes
if __name__ == "__main__":
    bt = Bst()
    in_list = [6, 4, 8, 2, 5, 7, 9, 1, 3, 10]
    for i in in_list:
        bt.add_node(i)
    print(bt.order())
